import React from "react";
import { useNavigate } from "react-router-dom";


const ReceiptModal = ({ receipt, onClose }) => {
  const navigate = useNavigate();

  if (!receipt) return null;

  const handleConfirm = () => {
    onClose(); // close modal
    navigate("/products"); // go back to product page
  };

  // Helper to safely format numbers
  const safeFixed = (num) => (typeof num === "number" ? num.toFixed(2) : "0.00");

  return (
    <div className="receipt-overlay">
      <div className="receipt-modal">
        <h2 className="receipt-title">🧾 Payment Receipt</h2>

        <div className="receipt-section">
          <p>
            <strong>Name:</strong> {receipt.name || "N/A"}
          </p>
          <p>
            <strong>Email:</strong> {receipt.email || "N/A"}
          </p>
          <p>
            <strong>Date:</strong>{" "}
            {receipt.timestamp
              ? new Date(receipt.timestamp).toLocaleString()
              : "N/A"}
          </p>
        </div>

        <hr />

        <table className="receipt-table">
          <thead>
            <tr>
              <th>Product</th>
              <th>Qty</th>
              <th>Price (₹)</th>
              <th>Subtotal (₹)</th>
            </tr>
          </thead>
          <tbody>
            {receipt.items && receipt.items.length > 0 ? (
              receipt.items.map((item, idx) => (
                <tr key={idx}>
                  <td>{item.name || "Unnamed"}</td>
                  <td>{item.qty || 0}</td>
                  <td>{safeFixed(item.price)}</td>
                  <td>{safeFixed(item.subtotal)}</td>
                </tr>
              ))
            ) : (
              <tr>
                <td colSpan="4">No items found</td>
              </tr>
            )}
          </tbody>
        </table>

        <hr />

        <div className="receipt-total">
          <h3>Total: ₹{safeFixed(receipt.total)}</h3>
        </div>

        <div className="receipt-actions">
          <button className="btn-confirm" onClick={handleConfirm}>
            ✅ Confirm Payment
          </button>
          <button className="btn-close" onClick={onClose}>
            ❌ Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default ReceiptModal;
